def validate(rows, compare=True):
 def need(x,msg):
  if not x:raise ValueError(msg)
 by={x['id']:x for x in rows if 'id' in x};ids=[x['id'] for x in rows if 'id' in x]
 need(len(ids)==len(set(ids)),'duplicate IDs')
 kinds=collections.Counter(x['t'] for x in rows);need(kinds['u']==2230,'source-unit inventory drift')
 sources={s:(R/v['p']).read_text().splitlines() for s,v in rows[0]['sources'].items()}
 for s,v in rows[0]['sources'].items():
  actual=subprocess.check_output(['git','hash-object',v['p']],text=True).strip();need(actual==v['blob'],'source blob changed')
 scoped=[u for u in rows if u['t']=='u' and 'C01' in u.get('scope',[])];need(len(scoped)==510,'C01 scope drift')
 allowed={'APPROVED_EXPLICIT','DERIVED_NECESSARY','OPEN_DECISION','PROPOSAL','EXAMPLE','CONTEXT','SUPERSEDED'}
 for u in scoped:
  need(u['st']=='RA' and u['review_status']=='SEMANTICALLY_VERIFIED_C01_ONLY','unreviewed C01 unit')
