   need(cl['classification'] in allowed,'bad clause status');a,z=cl['source_span'];need(u['a']<=a<=z<=u['z'],'clause out of source')
   for q in cl.get('requirements',[]):need(q in by and by[q]['t']=='req','bad clause requirement')
  for q in u['r']:need(u['id'] in by[q]['source_units'],'reverse source link broken')
 req=[x for x in rows if x['t']=='req'];tasks=[x for x in rows if x['t']=='task'];acs=[x for x in rows if x['t']=='ac'];tests=[x for x in rows if x['t']=='test'];deps=[x for x in rows if x['t']=='dependency']
 need((len(req),len(tasks),len(acs),len(tests),len(deps))==(40,13,40,40,23),'unexpected planning counts')
 behaviours={b['id'] for q in req for b in q['behaviours']};need(len(behaviours)==128,'atomic behaviour drift')
 for q in req:
