   s,ab=ref.split(':');ns=list(map(int,ab.split('-')));a,z=ns[0],ns[-1];need(1<=a<=z<=len(sources[s]),'invalid line reference');spans.append((s,a,z))
  expected={u['id'] for u in rows if u['t']=='u' and any(u['s']==s and u['a']<=z and u['z']>=a for s,a,z in spans)};need(expected==set(q['source_units']),'source spans/unit mapping mismatch')
  need(q['tasks'] and q['acceptance_criteria'] and q['tests'],'requirement missing downstream trace')
  for u in q['source_units']:need(q['id'] in by[u]['r'],'source reverse trace absent')
  for t in q['tasks']:need(q['id'] in by[t]['requirements'],'requirement-task reverse mismatch')
  linked_acs=[by[a] for a in q['acceptance_criteria']];linked_tests=[by[t] for t in q['tests']]
  for b in q['behaviours']:
   need(any(b['id'] in a['behaviours'] for a in linked_acs),'behaviour without AC');need(any(b['id'] in t['behaviours'] for t in linked_tests),'behaviour without test')
  need(q['counterexample_review']['result']=='CLOSED_AT_SPECIFICATION_LEVEL','open sufficiency review')
 for t in tasks:
  need(t['planning_status']=='IPA_ACCEPTED' and t['owner']=='C01','bad task acceptance/owner');need('/' not in t['implementation_owner'],'multiple unassigned owners')
  need(t['requirements'] and t['deliverable'] and t['acceptance_criteria'] and t['tests'] and t['code_evidence'],'empty task')
  need(t['implementation_authorization']=='NOT_GRANTED','implementation incorrectly authorized')
  for q in t['requirements']:need(t['id'] in by[q]['tasks'],'task-req reverse mismatch')
  for a in t['acceptance_criteria']:need(by[a]['task']==t['id'],'task-ac reverse mismatch')
  for x in t['tests']:need(by[x]['task']==t['id'],'task-test reverse mismatch')
  for x in t['code_evidence']:need(by[x]['task']==t['id'],'task-evidence reverse mismatch')
  for x in t['decision_gates']:need(t['id'] in by[x]['affected_tasks'],'task-decision mismatch')
  for x in t['contract_refs']:need(t['id'] in by[x]['tasks'],'task-contract mismatch')
  need(not t['decision_gates'] or t['implementation_status']=='BLOCKED_BY_DECISION','open decision not blocking implementation')
  for sub in t['subtasks']:need(sub['requirements'] and sub['acceptance_criteria'] and sub['deliverable'],'untraceable subtask')
 for a in acs:need(a['given'] and a['when'] and a['then'] and a['negative'] and a['boundary_or_concurrency'],'inadequate AC fields')
 for t in tests:
  need(t['execution_status']=='NOT_EXECUTED','definition mistaken for execution');need(len(t['cases'])==3 and t['environment'] and t['required_evidence'],'incomplete test definition')
  for a in t['acceptance_criteria']:need(t['id'] in by[a]['tests'],'test-ac reverse mismatch')
 edges=set();adj=collections.defaultdict(list)
 for d in deps:
  need(d['type'] in {'HARD','CONTRACT','POLICY','PREFERENCE'},'unknown dependency type');need(d['from'] in by and d['to'] in by,'bad dependency endpoint');need(d['reason'] and d['source_requirements'],'unjustified dependency')
  edges.add((d['from'],d['to'],d['type']));adj[d['from']].append(d['to'])
 need(len(edges)==23,'duplicate dependency')
 need(edges=={(d['task'],t['id'],d['type']) for t in tasks for d in t['dependencies']},'dependency representations disagree')
 seen=set();active=set()
 def visit(n):
  need(n not in active,'dependency cycle')
  if n in seen:return
  active.add(n)
  for m in adj[n]:visit(m)
  active.remove(n);seen.add(n)
 for t in tasks:visit(t['id'])
 for e in [x for x in rows if x['t']=='code_evidence']:
  blob=subprocess.check_output(['git','hash-object',e['path']],text=True).strip();need(blob==e['blob'],'code inspection blob drift');need(e['runtime_verified'] is False,'unproved runtime claim')
 if compare:
  old=[json.loads(l) for l in subprocess.check_output(['git','show','6a52b8ded941b39e4439b338e1c25f541a3b528e:docs/phase2/core/CORE_REGISTRY.jsonl'],text=True).splitlines()]
  need({x['id']:x for x in old if x['t']=='u' and 'C01' not in x.get('scope',[])}=={x['id']:x for x in rows if x['t']=='u' and 'C01' not in x.get('scope',[])},'out-of-C01 source modified')
  for k in ('req','task','epic'):need({x['id'] for x in old if x['t']==k}=={x['id'] for x in rows if x['t']==k},'existing IDs lost or invented')
 nested=[s['id'] for t in tasks for s in t['subtasks']]+[b['id'] for q in req for b in q['behaviours']]+[c['id'] for t in tests for c in t['cases']]
 need(len(nested)==len(set(nested)) and not set(nested)&set(ids),'duplicate nested ID')
 need(kinds['epic']==4 and kinds['policy_principle']==22 and kinds['candidate_disposition']==9,'preserved inventory drift')
 need(F.stat().st_size<1000000,'registry exceeds one million bytes')
 return {'records':len(rows),'source_units':2230,'C01_reviewed':510,'requirements':40,'atomic_behaviours':128,'enablers':4,'tasks':13,'subtasks':sum(len(t['subtasks']) for t in tasks),'dependencies':23,'AC':40,'test_definitions':40,'test_scenarios':120,'product_test_executions':0,'decision_gates':9,'contracts':7,'code_inspections':kinds['code_evidence']}
if __name__=='__main__':
 data=[json.loads(l) for l in F.read_text().splitlines()];print(json.dumps(validate(data),ensure_ascii=False,sort_keys=True))
